def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    moderate_bids = []
    high_bids = []

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if bid >= 90:
                    high_bids.append(float(bid))
                else:
                    moderate_bids.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    competitors = 1 + len(alive_opponents)
    expected_units = supply / float(WATER_REQ)
    scarcity = expected_units < competitors

    highest_prev = max(prev_bids) if prev_bids else 0.0
    moderate_anchor = max(moderate_bids) if moderate_bids else 0.0

    danger = 0
    if hp <= 3:
        danger += 2
    elif hp <= 5:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 1

    if no_water_days >= 2 or hp <= 2:
        bid = min(budget, max(78.0, moderate_anchor + 6.0, DAILY_SALARY * 1.05))
        return float(max(0.0, bid))

    if scarcity:
        if danger >= 2:
            target = max(62.0, moderate_anchor + 4.0)
        else:
            target = max(38.0, min(58.0, moderate_anchor + 1.5 if moderate_anchor > 0 else 44.0))
    else:
        if danger >= 2:
            target = max(42.0, moderate_anchor + 2.0 if moderate_anchor > 0 else 42.0)
        else:
            target = 16.0 if highest_prev >= 90.0 else 24.0

    if day >= 8 and hp <= 5:
        target += 8.0
    if budget < 140:
        target = min(target, 46.0 if danger < 3 else 68.0)
    if budget < 70:
        target = min(target, budget)

    bid = min(budget, target)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    bid = DAILY_SALARY * 0.5 

    # Adjust bid based on my HP
    if my_status['hp'] <= 2: 
        bid = DAILY_SALARY * 0.95
    elif my_status['hp'] == 3:
        bid = DAILY_SALARY * 0.8
    elif my_status['hp'] == 4:
        bid = DAILY_SALARY * 0.7
    else: # Healthy HP
        # Adjust bid based on supply and competition
        num_possible_winners = int(day_context['supply'] // WATER_REQ)

        if num_possible_winners == 0: 
            bid = max(bid, DAILY_SALARY * 0.85)
        elif num_possible_winners <= num_alive_opponents: 
            bid = max(bid, DAILY_SALARY * 0.65)
        else: 
            bid = min(bid, DAILY_SALARY * 0.45)

        # Adjust bid based on highest previous bid
        if highest_prev_bid > 0:
            if highest_prev_bid >= DAILY_SALARY * 0.8: 
                if my_status['hp'] > 4: 
                    bid = max(bid, highest_prev_bid * 0.9)
                else: 
                    bid = max(bid, highest_prev_bid + 5)
            elif highest_prev_bid >= DAILY_SALARY * 0.5: 
                bid = max(bid, highest_prev_bid + 2)
            else: 
                bid = max(bid, highest_prev_bid + 1)

    # Endgame strategy
    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2: 
        if my_status['hp'] <= 5: 
            bid = max(bid, DAILY_SALARY * 0.9)
        else: 
            bid = max(bid, DAILY_SALARY * 0.7)

    bid = min(bid, my_status['budget'])
    bid = max(bid, 0.01)

    return bid

